const $=id=>document.getElementById(id);const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(Number(n||0));const date=s=>s?new Intl.DateTimeFormat('en-US',{dateStyle:'medium'}).format(new Date(s)):'—';function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function notice(text,ok=true){$('notice').innerHTML=text?`<div class="notice ${ok?'ok':'bad'}">${esc(text)}</div>`:''}async function load(){try{const r=await fetch('/api/dashboard');const d=await r.json();if(!r.ok)throw Error(d.error);const s=d.summary||{},cfg=d.settings||{};$('needed').textContent=fmt(s.hoursNeeded);$('filled').textContent=fmt(s.hoursFilled);$('remaining').textContent=fmt(s.hoursRemaining);$('tbd').textContent=fmt(s.tbdAssignments);$('events').textContent=fmt(s.activeEvents);$('rate').textContent=`${Math.round(s.fillRate||0)}% of known/estimated demand`;$('open').textContent=`${s.openSlots||0} open volunteer positions`;$('assigned').textContent=`${s.assignedSlots||0} filled · ${s.totalAssignments||0} total positions`;$('last').textContent=date(s.lastSyncAt);$('estimateEnabled').checked=!!cfg.estimateUntimedEnabled;$('estimateHours').value=Number(cfg.estimateUntimedHours??6);$('estimateHours').disabled=!cfg.estimateUntimedEnabled;$('neededLabel').textContent=cfg.estimateUntimedEnabled?'Hours Needed (incl. estimates)':'Known Hours Needed';$('filledLabel').textContent=cfg.estimateUntimedEnabled?'Hours Filled (incl. estimates)':'Known Hours Filled';$('neededNote').textContent=cfg.estimateUntimedEnabled?`${fmt(s.estimatedHoursNeeded)} estimated`:`${s.tbdAssignments||0} assignments still TBD`;const p=d.programs||[];$('programs').className='rows';$('programs').innerHTML=p.length?p.map(x=>`<div class="row"><strong>${esc(x.name)}</strong><span>—</span><span>—</span><span>—</span><div><div class="bar"><i style="width:0%"></i></div><small>—</small></div></div>`).join(''):'<div class="empty">No program data yet.</div>';const e=d.events||[];$('eventList').innerHTML=e.length?e.map(x=>`<div class="event"><strong>${esc(x.title)}</strong><small>${date(x.eventDate)} · ${esc(x.location||'Location not set')}</small><div class="nums"><span>${fmt(x.hoursFilled)} filled hrs</span><span>${fmt(x.hoursNeeded)} needed hrs</span><span>${x.openSlots||0} open</span>${x.tbdQty>0?`<span>${x.tbdQty} TBD</span>`:''}</div><div class="bar"><i style="width:${x.hoursNeeded?Math.min(100,x.hoursFilled/x.hoursNeeded*100):0}%"></i></div></div>`).join(''):'<div class="empty">No active events have been synchronized.</div>';const v=d.volunteers||[];$('volunteers').className='';$('volunteers').innerHTML=v.length?v.slice(0,25).map(x=>`<div class="volrow"><div><strong>${esc(x.name)}</strong>${x.email?`<small>${esc(x.email)}</small>`:''}</div><b>${fmt(x.knownHours)}</b><span>${fmt(x.assignments)}</span><span>${fmt(x.tbdAssignments)}</span></div>`).join(''):'<div class="empty">No filled volunteer records yet.</div>'}catch(e){notice(e.message||'Unable to load dashboard',false)}}$('estimateEnabled').onchange=()=>{$('estimateHours').disabled=!$('estimateEnabled').checked};$('saveSettings').onclick=async()=>{const b=$('saveSettings');b.disabled=true;b.textContent='Saving…';notice('');try{const payload={estimateUntimedEnabled:$('estimateEnabled').checked,estimateUntimedHours:Number($('estimateHours').value)};const r=await fetch('/api/settings',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error);notice(payload.estimateUntimedEnabled?`Untimed assignments are estimated at ${payload.estimateUntimedHours} hours each.`:'Untimed assignments are excluded from hour totals and shown as TBD.',true);await load()}catch(e){notice(e.message||'Unable to save settings',false)}finally{b.disabled=false;b.textContent='Save'}};$('sync').onclick=async()=>{const b=$('sync');b.disabled=true;b.textContent='Syncing…';notice('');try{const r=await fetch('/api/sync',{method:'POST'});const d=await r.json();if(!r.ok)throw Error(d.error);notice(d.message,true);await load()}catch(e){notice(e.message||'Sync failed',false)}finally{b.disabled=false;b.textContent='Sync SignUpGenius'}};load();
